/* Ordered style composition; selectors and cascade remain local to this example. */
@import url("./01-design-tokens.css");
@import url("./02-aurora-mesh-background.css");
@import url("./03-layout-grid.css");
@import url("./04-dropdowns-controls.css");
@import url("./05-sidebar.css");
@import url("./06-main-workspace.css");
@import url("./07-draggable-kpi-grid.css");
@import url("./08-widgets-grid-draggable.css");
@import url("./09-projects-data-table.css");
@import url("./10-modal-slide-over.css");
@import url("./responsive.css");

:root {
    /* V1: Nordic Night (Default Theme) */
    --bg-base: #030712;
    --surface-glass: rgba(15, 23, 42, 0.55);
    --surface-glass-hover: rgba(30, 41, 59, 0.75);
    --border-glass: rgba(255, 255, 255, 0.12);
    --border-glass-strong: rgba(255, 255, 255, 0.22);
    --text-main: #f8fafc;
    --text-muted: #94a3b8;
    --text-dim: #64748b;
    --card-shadow: 0 12px 40px 0 rgba(0, 0, 0, 0.45), inset 0 1px 0 0 rgba(255, 255, 255, 0.15);

    --aurora-1: #3b82f6;
    --aurora-2: #8b5cf6;
    --aurora-3: #06b6d4;
    --aurora-4: #ec4899;
    --accent-glow: rgba(59, 130, 246, 0.4);

    --dropdown-bg: #0f172a;
    --tooltip-bg: rgba(15, 23, 42, 0.95);
    --transition-speed: 0.6s;
    --radius-lg: 20px;
    --radius-md: 14px;
    --radius-sm: 8px;
}

/* Variation 2: Dawn Glow (Warm Light Theme) */
body.v2-dawn {
    --bg-base: #faf8f5;
    --surface-glass: rgba(255, 255, 255, 0.65);
    --surface-glass-hover: rgba(255, 255, 255, 0.85);
    --border-glass: rgba(217, 119, 6, 0.15);

/* Aurora Mesh Background */
.aurora-container {
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    z-index: 0;
    overflow: hidden;
    filter: blur(80px);
    opacity: 0.75;
    pointer-events: none;
}

.aurora-blob {
    position: absolute;
    border-radius: 50%;
    mix-blend-mode: screen;
    animation: auroraFloat 22s infinite ease-in-out alternate;
    transition: background var(--transition-speed) ease;
}

body.v2-dawn .aurora-blob,
body.v6-pastel .aurora-blob {
    mix-blend-mode: multiply;
    opacity: 0.65;
}

.blob-1 {
    width: 55vw;
    height: 55vw;
    background: radial-gradient(circle, var(--aurora-1) 0%, transparent 70%);
    top: -15%;
    left: -10%;
    animation-delay: 0s;
}

.blob-2 {
    width: 60vw;
    height: 60vw;
    background: radial-gradient(circle, var(--aurora-2) 0%, transparent 70%);
    top: 15%;
    right: -15%;
    animation-delay: -5s;
    animation-duration: 26s;
}

.blob-3 {
    width: 50vw;
    height: 50

/* Layout Grid */
.app-layout {
    position: relative;
    z-index: 1;
    display: grid;
    grid-template-columns: 260px 1fr;
    grid-template-rows: 72px 1fr;
    grid-template-areas:
        "sidebar header"
        "sidebar main";
    min-height: 100vh;
}

/* Header */
.header {
    grid-area: header;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0 2rem;
    border-bottom: 1px solid var(--border-glass);
    background: var(--surface-glass);
    backdrop-filter: blur(20px);
    z-index: 10;
}

.header-left {
    display: flex;
    align-items: center;
    gap: 1.5rem;
}

.header-title-group h1 {
    font-size: 1.25rem;
    font-weight: 700;
    letter-spacing: -0.02em;
    background: linear-gradient(135deg, var(--text-main) 0%, var(--text-muted) 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

.header-right {
    display: flex;
    align-items: center;
    gap: 1rem;
}

/* Live Sync Toggle */
.li

/* Dropdowns & Controls */
.dropdown {
    position: relative;
}

.select-btn {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.55rem 1rem;
    background: var(--surface-glass);
    border: 1px solid var(--border-glass);
    border-radius: var(--radius-md);
    color: var(--text-main);
    font-family: inherit;
    font-size: 0.85rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s;
}

.select-btn:hover {
    border-color: var(--border-glass-strong);
    background: var(--surface-glass-hover);
}

.dropdown-menu {
    position: absolute;
    top: calc(100% + 8px);
    right: 0;
    min-width: 180px;
    background: var(--dropdown-bg);
    border: 1px solid var(--border-glass-strong);
    border-radius: var(--radius-md);
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.4);
    backdrop-filter: blur(20px);
    padding: 0.5rem;
    opacity: 0;
    visibility: hidden;
    transform: translateY(-8px);
    transition: all 0.25s cubic-bezier(0.4, 0, 0

/* Sidebar */
.sidebar {
    grid-area: sidebar;
    border-right: 1px solid var(--border-glass);
    background: var(--surface-glass);
    backdrop-filter: blur(20px);
    padding: 1.5rem 1rem;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    z-index: 10;
}

.brand-logo {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.5rem 0.5rem 1.5rem 0.5rem;
    border-bottom: 1px solid var(--border-glass);
    margin-bottom: 1.5rem;
}

.brand-icon {
    width: 36px;
    height: 36px;
    border-radius: 10px;
    background: linear-gradient(135deg, var(--aurora-1), var(--aurora-3));
    display: flex;
    align-items: center;
    justify-content: center;
    box-shadow: 0 0 15px var(--accent-glow);
}

.brand-title {
    font-size: 1.1rem;
    font-weight: 800;
    letter-spacing: -0.03em;
}

.brand-title span {
    color: var(--aurora-3);
}

/* Nav Accordion */
.nav-list {
    list-style: none;
    display: flex;
    flex-direction

/* Main Workspace */
.main-content {
    grid-area: main;
    padding: 2rem;
    overflow-y: auto;
    display: flex;
    flex-direction: column;
    gap: 1.8rem;
}

/* Dashboard Top Toolbar */
.dashboard-toolbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 1rem;
}

.toolbar-title h2 {
    font-size: 1.6rem;
    font-weight: 800;
    letter-spacing: -0.02em;
}

.toolbar-title p {
    color: var(--text-muted);
    font-size: 0.88rem;
}

/* View Mode Tabs */
.tabs-container {
    display: flex;
    background: var(--surface-glass);
    border: 1px solid var(--border-glass);
    padding: 0.25rem;
    border-radius: var(--radius-md);
    gap: 0.2rem;
}

.tab-btn {
    padding: 0.45rem 1rem;
    border: none;
    background: transparent;
    color: var(--text-muted);
    font-family: inherit;
    font-size: 0.82rem;
    font-weight: 600;
    border-radius: var(--radius-sm);
    cursor: pointer;
    transition: all 0.25s;
}

/* Draggable KPI Grid */
.kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(230px, 1fr));
    gap: 1.25rem;
}

.kpi-card {
    padding: 1.4rem;
    cursor: grab;
}

.kpi-card:active {
    cursor: grabbing;
}

.kpi-card.dragging {
    opacity: 0.4;
    transform: scale(0.98);
}

.kpi-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 0.8rem;
}

.kpi-title {
    font-size: 0.82rem;
    font-weight: 600;
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.kpi-icon-wrapper {
    width: 34px;
    height: 34px;
    border-radius: 10px;
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid var(--border-glass);
    display: flex;
    align-items: center;
    justify-content: center;
}

.kpi-value {
    font-size: 1.85rem;
    font-weight: 800;
    letter-spacing: -0.03em;
    margin-bottom: 0.4rem;
    font-family: 'JetBrains Mono', monospace;
}

.kpi-foot

/* Widgets Grid (Draggable) */
.widgets-grid {
    display: grid;
    grid-template-columns: 2fr 1fr;
    gap: 1.5rem;
}

@media (max-width: 1100px) {
    .widgets-grid {
        grid-template-columns: 1fr;
    }
    .app-layout {
        grid-template-columns: 1fr;
        grid-template-areas:
            "header"
            "main";
    }
    .sidebar {
        display: none;
    }
}

.widget-card {
    padding: 1.6rem;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
}

.widget-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 1.5rem;
}

.widget-title {
    font-size: 1.05rem;
    font-weight: 700;
}

.drag-handle {
    cursor: grab;
    color: var(--text-dim);
    padding: 0.2rem;
    border-radius: 4px;
}

.drag-handle:hover {
    color: var(--text-main);
    background: rgba(255, 255, 255, 0.1);
}

/* Interactive SVG Chart */
.chart-container {
    position: relative;
    width: 100%;

/* Projects Data Table */
.data-table-container {
    width: 100%;
    overflow-x: auto;
}

.data-table {
    width: 100%;
    border-collapse: collapse;
    text-align: left;
    font-size: 0.85rem;
}

.data-table th {
    padding: 0.8rem 1rem;
    color: var(--text-dim);
    font-weight: 600;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.05em;
    border-bottom: 1px solid var(--border-glass);
}

.data-table td {
    padding: 0.9rem 1rem;
    border-bottom: 1px solid rgba(255, 255, 255, 0.05);
    color: var(--text-muted);
}

.data-table tr:hover td {
    background: rgba(255, 255, 255, 0.04);
    color: var(--text-main);
}

.status-pill {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.2rem 0.6rem;
    border-radius: 100px;
    font-size: 0.75rem;
    font-weight: 600;
}

.status-pill.active {
    background: rgba(16, 185, 129, 0.15);
    color: #34d399;
    border: 1px solid rgba(16, 185, 129, 0.3);
}

.status-pill.de

/* Modal Slide-Over */
.modal-backdrop {
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    background: rgba(0, 0, 0, 0.6);
    backdrop-filter: blur(8px);
    z-index: 200;
    opacity: 0;
    visibility: hidden;
    transition: all 0.3s ease;
}

.modal-backdrop.active {
    opacity: 1;
    visibility: visible;
}

.slide-over {
    position: fixed;
    top: 0;
    right: 0;
    width: 440px;
    max-width: 90vw;
    height: 100vh;
    background: var(--dropdown-bg);
    border-left: 1px solid var(--border-glass-strong);
    box-shadow: -10px 0 40px rgba(0, 0, 0, 0.5);
    backdrop-filter: blur(25px);
    z-index: 201;
    transform: translateX(100%);
    transition: transform 0.35s cubic-bezier(0.4, 0, 0.2, 1);
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    padding: 2rem;
}

.modal-backdrop.active .slide-over {
    transform: translateX(0);
}

