/* Reflow the original workspace without scaling its content. */
.app-layout {
    grid-template-columns: 260px minmax(0, 1fr);
    grid-template-rows: auto 1fr;
}
.main-content, .widget-card, .kpi-card {
    min-width: 0;
}
.header {
    flex-wrap: wrap;
    gap: 16px;
    padding-block: 16px;
}
.header-left, .header-right, .widget-header {
    flex-wrap: wrap;
    gap: 12px;
}
.slide-over {
    height: 100dvh;
    overflow-y: auto;
}
@media (max-width: 900px) {
    .app-layout {
        grid-template-columns: minmax(0, 1fr);
        grid-template-areas: "header" "sidebar" "main";
        grid-template-rows: auto auto auto;
    }
    .sidebar {
        border-right: 0;
        border-bottom: 1px solid var(--border-glass);
        padding: 20px;
    }
    .widgets-grid {
        grid-template-columns: minmax(0, 1fr);
    }
}
@media (max-width: 600px) {
    .header, .main-content {
        padding: 16px;
    }
    .kpi-grid {
        grid-template-columns: minmax(0, 1fr);
