document.querySelectorAll('.dropdown').forEach(dropdown => {
    const btn = dropdown.querySelector('.select-btn');
    btn.addEventListener('click', (e) => {
        e.stopPropagation();
        dropdown.classList.toggle('active');
    });
});

window.addEventListener('click', () => {
